from openai import OpenAI
import re

client = OpenAI()
AGENTS = {
    "math": lambda q: f"math: {eval(q)}",
    "echo": lambda q: f"echo: {q}",
}

def supervise(q: str) -> str:
    r = client.chat.completions.create(
        model="{{model_name}}",
        messages=[{"role": "user",
                   "content": f"Route to one of {list(AGENTS)}. Reply: AGENT:<name> ARGS:<args>\nQ: {q}"}],
    )
    m = re.search(r"AGENT:(\w+)\s+ARGS:(.+)", r.choices[0].message.content)
    if not m: return "no route"
    return AGENTS[m.group(1)](m.group(2).strip())
